(ns pgmalli.impl.files-test
  "The config and the text of a generated file; no database."
  (:require [clojure.string :as str]
            [clojure.test :refer [deftest is]]
            [pgmalli.impl.files :as files]))

(deftest generated-data-must-be-edn
  (is (thrown? clojure.lang.ExceptionInfo (files/edn-string {:registry {:x [:fn (fn [_] true)]}})))
  (let [s (files/edn-string {:registry {:pg.public/t [:map [:a ['inst? {:pg/type "timestamptz"}]]]}})]
    (is (str/starts-with? s ";; generated by pgmalli"))
    (is (not (str/includes? s "#:pg")))))

(deftest a-misspelt-config-key-names-the-key-meant
  (let [e (is (thrown-with-msg? clojure.lang.ExceptionInfo #"invalid config: .*:out_dir .*should be spelled :out-dir" (files/config {:out_dir "x"})))]
    (is (= :pgmalli.error/invalid-config (:pgmalli/error (ex-data e))))
    (is (= :cognitect.anomalies/incorrect (:cognitect.anomalies/category (ex-data e))))))

(deftest schemas-as-a-string-is-an-error
  (is (thrown-with-msg? clojure.lang.ExceptionInfo #"should be a vector of schema names" (files/config {:schemas "public"}))))

(deftest a-config-error-leaves-the-db-map-out
  (let [e (is (thrown? clojure.lang.ExceptionInfo (files/config {:db {:password "s3cret"} :schemas "public"})))]
    (is (not (str/includes? (pr-str (ex-data e)) "s3cret")))))
